const papers = [];

for (const item of $input.all()) {
  const data = item.json;

  if (data.paperId) {
    papers.push({
      id: data.paperId,
      title: data.title || 'Untitled',
      abstract: data.abstract || 'No abstract available',
      authors: data.authors?.map(a => a.name).join(', ') || 'Unknown',
      year: data.year || 'N/A',
      citations: data.citationCount || 0,
      venue: data.venue || 'Unknown venue',
      doi: data.externalIds?.DOI || null,
      pdfUrl: data.openAccessPdf?.url || null,
      source: 'Semantic Scholar'
    });
  }

  if (data.DOI && !data.paperId) {
    papers.push({
      id: data.DOI,
      title: data.title?.[0] || 'Untitled',
      abstract: data.abstract || 'No abstract available',
      authors: data.author?.map(a => `${a.given} ${a.family}`).join(', ') || 'Unknown',
      year: data.published?.['date-parts']?.[0]?.[0] || 'N/A',
      citations: data['[REDACTED]'] || 0,
      venue: data['container-title']?.[0] || 'Unknown venue',
      doi: data.DOI,
      pdfUrl: data.link?.find(l => l['content-type'] === 'application/pdf')?.URL || null,
      source: 'CrossRef'
    });
  }
}

papers.sort((a, b) => b.citations - a.citations);

return papers.map(paper => ({ json: paper }));

