const data = $input.first().json;
const review = data.output || data.text || 'Review generation failed';
const aggData = $('Aggregate Review Data').first().json;
const stats = aggData.statistics;
const topic = aggData.researchTopic;

const markdown = `# Literature Review: ${topic}

**Generated:** ${new Date().toLocaleDateString()}
**Papers Analyzed:** ${stats.totalPapers}
**Citation Range:** ${stats.yearRange.earliest} - ${stats.yearRange.latest}

---

${review}

---

## Appendix: Paper Analysis Summary

| Paper | Year | Citations | Category | Relevance |
|-------|------|-----------|----------|------------|
${aggData.allAnalyses.map(a => 
  `| ${a.paper.title.substring(0, 50)}... | ${a.paper.year} | ${a.paper.citations} | ${a.analysis.[REDACTED] || 'N/A'} | ${a.analysis.relevanceScore || 'N/A'}/10 |`
).join('\n')}

---

*This literature review was generated using an automated workflow powered by n8n.*
`;

return [{ json: { markdown, topic, generatedAt: new Date().toISOString() } }];

